import { existsSync, mkdirSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';

/**
 * Generate a CI pipeline template with branch names from branchConfig.
 *
 * @param {'github-actions'|'azure-devops'} ciProvider
 * @param {object} overlayConfig
 * @param {string} targetDir
 * @returns {string[]} Array of generated file paths
 */
export function generateCITemplate(ciProvider, overlayConfig, targetDir) {
  const { branchConfig } = overlayConfig;

  // Determine branch names for triggers
  const allBranches = branchConfig
    ? branchConfig.branches.map(b => b.name)
    : ['main', 'develop'];

  // Push triggers: only branches agents can push to (non-pattern)
  const pushBranches = branchConfig
    ? branchConfig.agentAllowed.filter(b => !b.includes('*'))
    : ['develop'];

  // PR triggers: all named branches
  const prBranches = allBranches;

  if (ciProvider === 'github-actions') {
    return generateGitHubActions(targetDir, prBranches, pushBranches);
  } else if (ciProvider === 'azure-devops') {
    return generateAzureDevOps(targetDir, prBranches, pushBranches);
  }

  return [];
}

function generateGitHubActions(targetDir, prBranches, pushBranches) {
  const prList = prBranches.map(b => `      - ${b}`).join('\n');
  const pushList = pushBranches.map(b => `      - ${b}`).join('\n');

  const yaml = `# CI Pipeline — Generated by ai-workflow-overlay
# Fill in the {{PLACEHOLDER}} values for your project's specific commands
#
# Placeholder reference:
#   {{SETUP_STEPS}}      — Runtime setup actions (e.g., actions/setup-node@v4 with node-version,
#                          actions/setup-python@v5, actions/setup-dotnet@v4). Replace the comment
#                          line with one or more "- uses:" steps appropriate for your stack.
#   {{INSTALL_COMMAND}}  — Command to install project dependencies
#                          Node.js example:  npm ci
#                          Python example:   pip install -r requirements.txt
#                          .NET example:     dotnet restore
#   {{LINT_COMMAND}}     — Command to run linting and formatting checks
#                          Node.js example:  npm run lint
#                          Python example:   ruff check .
#                          .NET example:     dotnet format --verify-no-changes
#   {{TEST_COMMAND}}     — Command to run the test suite
#                          Node.js example:  npm test
#                          Python example:   pytest
#                          .NET example:     dotnet test
#   {{BUILD_COMMAND}}    — Command to produce a production build artifact
#                          Node.js example:  npm run build
#                          Python example:   python -m build
#                          .NET example:     dotnet publish -c Release

name: CI

on:
  pull_request:
    branches:
${prList}
  push:
    branches:
${pushList}

jobs:
  lint:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4
      # {{SETUP_STEPS}} — Add runtime setup here (e.g., actions/setup-node, actions/setup-python, actions/setup-dotnet)
      - name: Install dependencies
        run: "{{INSTALL_COMMAND}}"
      - name: Lint
        run: "{{LINT_COMMAND}}"

  test:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4
      # {{SETUP_STEPS}}
      - name: Install dependencies
        run: "{{INSTALL_COMMAND}}"
      - name: Test
        run: "{{TEST_COMMAND}}"

  build:
    runs-on: ubuntu-latest
    needs: [lint, test]
    steps:
      - uses: actions/checkout@v4
      # {{SETUP_STEPS}}
      - name: Install dependencies
        run: "{{INSTALL_COMMAND}}"
      - name: Build
        run: "{{BUILD_COMMAND}}"
`;

  const destDir = join(targetDir, '.github', 'workflows');
  mkdirSync(destDir, { recursive: true });
  const outputPath = join(destDir, 'ci.yml');
  writeFileSync(outputPath, yaml, 'utf8');

  return [outputPath];
}

function generateAzureDevOps(targetDir, prBranches, pushBranches) {
  const triggerList = pushBranches.map(b => `      - ${b}`).join('\n');
  const prList = prBranches.map(b => `      - ${b}`).join('\n');

  const yaml = `# CI Pipeline — Generated by ai-workflow-overlay
# Fill in the {{PLACEHOLDER}} values for your project's specific commands
#
# Placeholder reference:
#   {{SETUP_STEPS}}      — Runtime setup tasks (e.g., NodeTool@0 with versionSpec,
#                          UsePythonVersion@0, DotNetCoreCLI@2 with command: 'restore').
#                          Replace the comment line with one or more "- task:" steps
#                          appropriate for your stack.
#   {{INSTALL_COMMAND}}  — Command to install project dependencies
#                          Node.js example:  npm ci
#                          Python example:   pip install -r requirements.txt
#                          .NET example:     dotnet restore
#   {{LINT_COMMAND}}     — Command to run linting and formatting checks
#                          Node.js example:  npm run lint
#                          Python example:   ruff check .
#                          .NET example:     dotnet format --verify-no-changes
#   {{TEST_COMMAND}}     — Command to run the test suite
#                          Node.js example:  npm test
#                          Python example:   pytest
#                          .NET example:     dotnet test
#   {{BUILD_COMMAND}}    — Command to produce a production build artifact
#                          Node.js example:  npm run build
#                          Python example:   python -m build
#                          .NET example:     dotnet publish -c Release

trigger:
  branches:
    include:
${triggerList}

pr:
  branches:
    include:
${prList}

pool:
  vmImage: 'ubuntu-latest'

stages:
  - stage: Validate
    jobs:
      - job: Lint
        steps:
          - checkout: self
          # {{SETUP_STEPS}}
          - script: "{{INSTALL_COMMAND}}"
            displayName: Install dependencies
          - script: "{{LINT_COMMAND}}"
            displayName: Lint

      - job: Test
        steps:
          - checkout: self
          # {{SETUP_STEPS}}
          - script: "{{INSTALL_COMMAND}}"
            displayName: Install dependencies
          - script: "{{TEST_COMMAND}}"
            displayName: Test

  - stage: Build
    dependsOn: Validate
    jobs:
      - job: Build
        steps:
          - checkout: self
          # {{SETUP_STEPS}}
          - script: "{{INSTALL_COMMAND}}"
            displayName: Install dependencies
          - script: "{{BUILD_COMMAND}}"
            displayName: Build
`;

  const outputPath = join(targetDir, 'azure-pipelines.yml');
  writeFileSync(outputPath, yaml, 'utf8');

  return [outputPath];
}
